export interface BatchStatus {
  batchId: string;
  resource: "availability" | "rates" | "restrictions";
  createdAt: string;
  requestedCells: number;
  acceptedCells: number;
  noopCells: number;
  rejected: Array<{
    cells: number;
    error: string;
  }>;
  status: "landed" | "pending" | "failed";
  pendingCells: number;
  /** Cells of this batch the channel manager refused: held, not re-sent (§6.6). More than 0 reads failed */
  parkedCells: number;
  lastError: string | null;
}

export interface SyncStatus {
  propertyId: number;
  /** true on a sandbox property (a zsk_test_ key): pushes land in our record and stop there, so IN_SYNC means recorded */
  sandbox: boolean;
  /** false = nothing is pushed; ask ZimmerStack support */
  ariAuthoritative: boolean;
  inventory: {
    state: "IN_SYNC" | "PENDING" | "OUT_OF_SYNC" | "DISABLED";
    pendingCells: number;
    lastOkAt: string | null;
    lastError: string | null;
    outOfSyncSince: string | null;
  };
  rates: {
    /** rate/restriction cells waiting for the projector */
    dirtyCells: number;
    /** rate/restriction cells the channel manager refused: held, no longer re-sent, their batch reads failed. Send a corrected value for those nights (§6.6) */
    parkedCells: number;
    lastPushAt: string | null;
    lastErrorAt: string | null;
    lastError: string | null;
  };
  /** Where this integration stands with the channel shield. Reads and bookings are never affected */
  shield: {
    /** CLEAR nothing held against the integration · WATCH noted, nothing refused · PAUSED only writes that close inventory are accepted · SUSPENDED every write refused until ZimmerStack releases it */
    level: "CLEAR" | "WATCH" | "PAUSED" | "SUSPENDED";
    /** Why, when the level is not CLEAR */
    reason: string | null;
    /** When a pause ends on its own (ISO instant); null = until released, or not paused */
    until: string | null;
  };
  newestPendingBatch: {
    batchId: string;
    resource: "availability" | "rates" | "restrictions";
    createdAt: string;
    requestedCells: number;
    acceptedCells: number;
    noopCells: number;
    rejected: Array<{
      cells: number;
      error: string;
    }>;
    status: "landed" | "pending" | "failed";
    pendingCells: number;
    /** Cells of this batch the channel manager refused: held, not re-sent (§6.6). More than 0 reads failed */
    parkedCells: number;
    lastError: string | null;
  } | null;
}

export interface BookingCreate {
  /** Your own reservation id; unique per property. A retried POST with the same value returns the same booking while it is live and yours; after a cancel, a new stay needs a new reference (409 EXTERNAL_REFERENCE_REUSED otherwise) */
  externalReference: string;
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkIn: string;
  /** Exclusive: the checkout day is not a night */
  checkOut: string;
  /** ISO 4217; must equal the property's (GET /property) */
  currency: string;
  /** Who booked; found or created in the PMS by phone */
  guest: {
    /** Full name as the guest typed it */
    name: string;
    /** Guest phone, digits with an optional leading + */
    phone: string & string;
    /** Guest email, when you have it; we write to it only if the owner switches our confirmation on */
    email?: string;
    /** Special requests for the desk; shown in the PMS, never sent anywhere */
    notes?: string;
  };
  /** One entry per ROOM; two rooms of the same type are two entries */
  rooms: Array<{
    /** ZimmerStack room type id: roomTypes[].id from GET /catalog, never guessed */
    roomTypeId: number;
    /** Optional: the plan the guest booked, ratePlans[].id from GET /catalog; must belong to roomTypeId. Decides the meal plan; omitted = room only (EP) */
    ratePlanId?: number;
    /** Adults in this room; at most the room type's maxAdults */
    adults: number;
    /** Children in this room; default 0; at most the room type's maxChildren */
    children?: number;
    /** The nightly price YOU charged for this room, MAJOR units (e.g. 4500 or "4500.00"), 1 to 21474836, taxes as you sold them */
    nightlyRate: number | string;
  }>;
  /** Omit when nothing was collected; an amount above 0 needs the bookings:payments scope */
  payment?: {
    /** What you collected so far, MAJOR units; 0 = nothing collected (pay at hotel); never more than the stay's total */
    amount: number | string;
    /** How you collected it */
    method: "ONLINE" | "CARD" | "UPI" | "NETBANKING" | "CASH";
    /** Your gateway's payment or transaction id */
    reference?: string;
  };
  /** Booking-level remarks for the desk (promo code, source page) */
  notes?: string;
}

export interface BookingCancel {
  /** Why; kept on the booking's activity log */
  reason?: string;
}

export interface BookingsQuery {
  /** Created on or after this instant (ISO 8601); default: the last 7 days */
  since?: string;
  /** Your own reservation id; unique per property. A retried POST with the same value returns the same booking while it is live and yours; after a cancel, a new stay needs a new reference (409 EXTERNAL_REFERENCE_REUSED otherwise) */
  externalReference?: string;
  /** 1 to 100; default 50 */
  limit?: number;
}

export interface Booking {
  bookingId: number;
  reference: string;
  externalReference: string | null;
  status: "UPCOMING" | "INHOUSE" | "COMPLETED" | "CANCELLED" | "NOSHOW";
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkIn: string;
  /** Hotel-local calendar date, YYYY-MM-DD */
  checkOut: string;
  nights: number;
  currency: string;
  /** MAJOR units, two decimals: the whole stay */
  totalAmount: string;
  /** MAJOR units, two decimals: collected so far */
  totalPaid: string;
  /** MAJOR units, two decimals: owed at the hotel */
  balanceDue: string;
  guest: {
    name: string;
    phone: string;
    email: string | null;
  };
  rooms: Array<{
    bookingRoomId: number;
    roomTypeId: number;
    ratePlanId: number | null;
    mealPlan: "EP" | "CP" | "MAP" | "AP";
    adults: number;
    children: number;
    /** MAJOR units, two decimals */
    nightlyRate: string;
    status: "UPCOMING" | "CHECKEDIN" | "CHECKEDOUT" | "CANCELLED" | "NOSHOW";
  }>;
  inventory: {
    eventRecorded: boolean;
    /** false = this property has no channel manager; nothing is pushed */
    channelManager: boolean;
    pushedBy: "inventory-drain";
  };
  replay: boolean;
  createdAt: string;
  cancelledAt: string | null;
}

