export interface SandboxBookingCreate {
  /** A room type of the sandbox (GET /catalog) */
  roomTypeId: number;
  /** Arrival, YYYY-MM-DD in the property's timezone; today or later, within the horizon */
  checkIn: string;
  /** 1–30; checkout = checkIn + nights */
  nights: number;
  /** Rooms of this type the guest books (1–5); default 1 */
  rooms?: number;
  /** Adults per room; default 2 */
  adults?: number;
  /** The guest's name; default a fictional one */
  guestName?: string;
  /** The channel the booking pretends to arrive from; default Booking.com. "Website" simulates a booking on the hotel's own website (our booking engine): it sends direct.booking.created and is listed by GET /direct-bookings, not GET /channel-bookings */
  otaName?: "Booking.com" | "Expedia" | "Agoda" | "Airbnb" | "MakeMyTrip" | "Goibibo" | "Website";
  /** true = the channel collected the money (for Website: the guest paid online), so totalPaid equals the total; default false (pay at the property) */
  paidByOta?: boolean;
}

export interface SandboxBookingModify {
  /** New arrival, YYYY-MM-DD in the property's timezone; today or later */
  checkIn?: string;
  /** New length of stay, 1–30 */
  nights?: number;
  /** New number of rooms, 1–5 */
  rooms?: number;
  /** New adults per room */
  adults?: number;
  /** The guest renamed, as a channel sometimes does */
  guestName?: string;
}

export interface Channels {
  /** When the connection list was last captured; null when never */
  asOf: string | null;
  channels: Array<{
    /** The channel manager's id for this connection */
    channelId: string;
    /** The channel: BookingCom, Expedia, Agoda, Airbnb, GoMMT, … */
    kind: string;
    /** The connection's title in the channel manager */
    title: string | null;
    /** When our record last saw this connection (the nightly settings sweep) */
    seenAt: string;
    /** Unresolved problems the channel manager reported for this connection */
    openIssues: Array<{
      /** sync_error · rate_error · disconnect_channel · inventory_out_of_sync · … */
      event: string;
      raisedAt: string;
    }>;
    /** This channel's price modifier (§2.8): the steps the channel manager applies, in order, to every price it sends this channel. [] = prices go as they are. null = the channel holds a rule set by hand in the channel manager that this API cannot express; PUT /channels/{channelId}/modifier replaces it */
    modifier: Array<{
      /** Raise or lower what this channel is sent */
      action: "increase" | "decrease";
      /** percent of the price, or a fixed amount in MAJOR units of the property's currency */
      type: "percent" | "fixed";
      /** How much: 18 with type percent is 18 %; 200 with type fixed is 200.00 in the property's currency. Always positive: choose decrease instead of a minus sign. Two decimals at most */
      value: number;
    }> | null;
    /** A separate adjustment the owner set for this channel in the ZimmerStack Channels app, applied before the modifier. Read-only here; null = none */
    markupPlan: {
      /** markup: this channel sells a copy of each plan priced a fixed step from it · manual: this channel has prices of its own for some nights */
      mode: "markup" | "manual";
      direction: "increase" | "decrease";
      /** Percent of the price, when the step is a percentage */
      percent: number | null;
      /** MAJOR units, when the step is a fixed amount */
      amount: number | null;
    } | null;
  }>;
  /** Unresolved problems not tied to one connection (for example the inventory pipe out of sync) */
  propertyIssues: Array<{
    event: string;
    raisedAt: string;
  }>;
}

export interface ModifierWrite {
  /** The whole modifier, in the order it is applied; replaces what the channel holds. At most 5 steps. An empty list removes it: prices go to the channel as they are */
  steps: Array<{
    /** Raise or lower what this channel is sent */
    action: "increase" | "decrease";
    /** percent of the price, or a fixed amount in MAJOR units of the property's currency */
    type: "percent" | "fixed";
    /** How much: 18 with type percent is 18 %; 200 with type fixed is 200.00 in the property's currency. Always positive: choose decrease instead of a minus sign. Two decimals at most */
    value: number;
  }>;
}

export interface ModifierResult {
  channelId: string;
  /** The channel: BookingCom, Expedia, Agoda, Airbnb, GoMMT, … */
  kind: string;
  title: string | null;
  /** What the channel holds now */
  modifier: Array<{
    /** Raise or lower what this channel is sent */
    action: "increase" | "decrease";
    /** percent of the price, or a fixed amount in MAJOR units of the property's currency */
    type: "percent" | "fixed";
    /** How much: 18 with type percent is 18 %; 200 with type fixed is 200.00 in the property's currency. Always positive: choose decrease instead of a minus sign. Two decimals at most */
    value: number;
  }>;
  /** false when the channel already held exactly these steps: nothing was sent to the channel manager and nothing was counted */
  changed: boolean;
  /** When it takes effect. Always: "Saving a modifier makes the channel manager send that channel every date again, so prices already on the channel move to the new rule within minutes." */
  notice: string;
}

export interface RatesResendAccepted {
  /** Hotel-local calendar date, YYYY-MM-DD */
  from: string;
  /** Hotel-local calendar date, YYYY-MM-DD */
  to: string;
  /** Rate-plan nights marked to be sent again. They travel like any write: watch rates.dirtyCells on GET /sync fall to 0 */
  cells: number;
  /** Nights left out because the channel manager refused their value earlier (rates.parkedCells on GET /sync): send a corrected value for those */
  parkedLeft: number;
  /** GET path that says when it has landed */
  watch: string;
  notice: string;
}

